using DzLegal.CoreLogic.Reader.Cues;

namespace DzLegal.CoreLogic.Reader.Tests;

/// <summary>
/// The cue verbs in every person, gender and number, generated by rule from their stems (the owner, 18 November 2026:
/// lawyers write «لا ننفي» and «لا أنكر», not only «لا ينفي»).
/// </summary>
public sealed class CueVerbFormTests
{
    [Fact]
    public void ARegularPresentHasEveryPerson()
    {
        var forms = CueEngine.Present("نكر");
        string[] expected = ["انكر", "ننكر", "تنكر", "ينكر", "تنكرين", "تنكران", "ينكران", "تنكرون", "ينكرون", "تنكرن", "ينكرن", "ينكروا", "تنكري"];
        Assert.All(expected, form => Assert.Contains(form, forms));
    }

    [Fact]
    public void AStemEndingInYaDropsItBeforeWawAndInTheFeminineSecondPerson()
    {
        var forms = CueEngine.Present("نفي");
        string[] expected = ["انفي", "ننفي", "تنفي", "ينفي", "ينفون", "تنفون", "ينفوا", "تنفين", "ينفيان", "ينفين"];
        Assert.All(expected, form => Assert.Contains(form, forms));
        Assert.DoesNotContain("ينفيون", forms);
        Assert.DoesNotContain("تنفيي", forms);
    }

    [Fact]
    public void APerfectHasEveryPerson()
    {
        string[] expected = ["امتنع", "امتنعت", "امتنعنا", "امتنعوا", "امتنعتم", "امتنعتن", "امتنعن", "امتنعا", "امتنعتا", "امتنعتما"];
        Assert.Equal(expected, CueEngine.Perfect("امتنع"));
    }

    [Fact]
    public void TheTablesHoldTheGeneratedFormsAndKeepEveryOldOne()
    {
        string[] oldDisputes = ["ينكر", "تنكر", "ينفي", "تنفي", "ينازع", "تنازع", "يدعي", "تدعي", "يزعم", "تزعم", "يتمسك", "تتمسك", "يطعن", "تطعن", "يعترض", "تعترض", "يدفع ب", "تدفع ب"];
        Assert.All(oldDisputes, form => Assert.Contains(form, CueEngine.DisputeCues));
        Assert.All(new[] { "ننفي", "انكر", "نتمسك", "يدفعون ب", "ينازعون" }, form => Assert.Contains(form, CueEngine.DisputeCues));
        string[] oldRefusals = ["امتنع", "امتناع", "رفض", "تخلف", "تقاعس", "احجم", "اغفل", "اهمل"];
        Assert.All(oldRefusals, form => Assert.Contains(form, CueEngine.RefusalCues));
        Assert.Contains("رفضنا", CueEngine.RefusalCues);
    }

    [Fact]
    public void AFirstPersonDisputeVerbAfterANegationAdmits()
    {
        var engine = CueEngine.Load(Path.Combine(AppContext.BaseDirectory, "cues.json"));
        var vote = engine.Vote("لا ننكر أننا اقترضنا منه المبلغ", "money_lent");
        Assert.NotNull(vote);
        Assert.Equal(Contracts.Polarity.Stated, vote.Polarity);
    }
}
